<script lang="ts" setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { Alert as AAlert,Button as AButton,Card as ACard,Checkbox as ACheckbox,Form as AForm,FormItem as AFormItem,Input as AInput,Menu as AMenu,MenuItem as AMenuItem,Select as ASelect,Tabs as ATabs,TabPane as ATabPane,message } from 'ant-design-vue';
type Server={id:string;domain:string;listenPort:number;sslEnabled:boolean;accessLog?:string;errorLog?:string;rootPath?:string;hideVersion:boolean;responseHeaders:string[]};const route=useRoute(),router=useRouter(),server=ref<Server>(),section=ref('domain'),centerId=String(route.query.centerId||''),serverId=String(route.query.serverId||''),tab=ref('basic');const labels:{key:string,label:string}[]=[['domain','域名设置'],['root','网站目录'],['index','默认文档'],['rate','流量限制'],['proxy','Location 配置'],['access','密码访问'],['tls','HTTPS'],['static','伪静态'],['referer','防盗链'],['redirect','重定向'],['other','其他']].map(([key,label])=>({key,label}));
async function request<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers??{})}});if(!r.ok)throw new Error('请求失败');return r.status===204?undefined as T:r.json() as Promise<T>}async function load(){try{const all=await request<Server[]>(`/centers/${centerId}/http/servers`);server.value=all.find(v=>v.id===serverId)}catch{message.error('加载 Server 失败')}}async function save(){if(!server.value)return;try{await request(`/centers/${centerId}/http/servers/${serverId}/directives`,{method:'PUT',body:JSON.stringify({rootPath:server.value.rootPath,hideVersion:server.value.hideVersion,responseHeaders:server.value.responseHeaders})});message.success('Server 配置已保存，发布后生效')}catch{message.error('保存失败')}}onMounted(load);const title=computed(()=>server.value?`${server.value.domain}:${server.value.listenPort}`:'Server 配置');
</script>
<template><div class="ops-page"><a-card :bordered="false"><div class="server-header"><a-button type="link" @click="router.back()">← 返回</a-button><strong>{{title}}</strong><a-tabs v-model:active-key="tab"><a-tab-pane key="basic" tab="基本"/><a-tab-pane key="logs" tab="日志"/><a-tab-pane key="file" tab="配置文件"/></a-tabs></div><div class="server-layout"><a-menu v-model:selected-keys="section" mode="inline" class="server-menu"><a-menu-item v-for="item in labels" :key="item.key">{{item.label}}</a-menu-item></a-menu><main><a-alert class="mb-4" type="info" show-icon :message="`当前中心：${centerId}；当前 Server：${title}`"/><template v-if="section==='domain'"><a-form layout="vertical"><a-form-item label="域名"><a-input :value="server?.domain" disabled/></a-form-item><a-form-item label="监听端口"><a-input :value="server?.listenPort" disabled/></a-form-item></a-form></template><template v-else-if="section==='root'"><a-form layout="vertical"><a-form-item label="root 内容目录"><a-input v-model:value="server!.rootPath" placeholder="/srv/openresty-content/site-a"/></a-form-item><a-button type="primary" @click="save">保存</a-button></a-form></template><template v-else-if="section==='tls'"><a-alert type="info" show-icon message="TLS 证书与监听配置由 Server 基础字段管理；证书可在创建或编辑 Server 时选择。"/></template><template v-else-if="section==='proxy'"><a-button type="primary" @click="router.push({path:'/openresty/http-locations',query:{centerId,serverId,nodeId:route.query.nodeId}})">管理 Location 与 API</a-button></template><template v-else-if="section==='other'"><a-form layout="vertical"><a-form-item><a-checkbox v-model:checked="server!.hideVersion">隐藏版本并清除 Server 响应头</a-checkbox></a-form-item><a-form-item label="响应头与安全头"><a-select v-model:value="server!.responseHeaders" mode="tags" :token-separators="[',']"/></a-form-item><a-button type="primary" @click="save">保存</a-button></a-form></template><template v-else><a-alert type="info" show-icon :message="`${labels.find(v=>v.key===section)?.label} 将在对应 Location 配置中维护；点击“反向代理”可进入路由配置。`"/></template></main></div></a-card></div></template>
<style scoped>.server-header{display:flex;align-items:center;gap:16px}.server-header :deep(.ant-tabs){margin-left:12px}.server-layout{display:grid;grid-template-columns:150px minmax(0,1fr);gap:24px;margin-top:16px}.server-menu{border-inline-end:1px solid var(--ant-color-border-secondary)}main{min-height:420px;padding:8px 12px}@media(max-width:768px){.server-layout{grid-template-columns:1fr}.server-menu{border:0}}</style>
